arguments.new_string:
export type Effort = "low" | "medium" | "high" | "max" | "ultracode";

export const EFFORT_LEVELS: Record<Effort, { maxIterations: number; hint: string }> = {
  low: {
    maxIterations: 6,
    hint: "Work quickly. Prefer the most direct path. Skip optional verification.",
  },
  medium: {
    maxIterations: 14,
    hint: "Balance speed and care. Verify changes that could break things.",
  },
  high: {
    maxIterations: 28,
    hint: "Be thorough. Read relevant context before editing, verify your work by running it where possible.",
  },
  max: {
    maxIterations: 50,
    hint: "Be exhaustive. Explore broadly, consider edge cases, verify everything you produce, and double-check results before finishing.",
  },
  ultracode: {
    maxIterations: Number.POSITIVE_INFINITY,
    hint: [
      "ULTRACODE: full orchestration mode, no round limit. Follow this workflow strictly:",
      "1. PLAN — investigate enough to understand the task, then state a short plan.",
      "2. TODOS — call todo_write with the plan as a checklist; keep statuses updated as you work (exactly one item in_progress at a time).",
      "3. DELEGATE — split independent work across subagents with spawn_agent (returns instantly).",
      "4. WORK WHILE THEY WORK — keep making progress yourself, then collect with await_agents.",
      "5. VERIFY — run builds/tests, fix failures, repeat until everything passes.",
      "6. Only conclude when every todo is done and verified.",
    ].join("\n"),
  },
};
